using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioInvertComponentsValidation
{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static StudioModelEditor editor;static StudioModelDocument doc;static int checks;
 static object Call(string n,params object[] a)=>typeof(StudioModelEditor).GetMethods(F).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length).Invoke(editor,a);
 static void Check(bool b,string s){if(!b)throw new Exception(s);checks++;}
 static void Reset(){UnityEditor.Undo.ClearAll();StudioUndo.ClearForTests();StudioUndo.IncrementCurrentGroup();}
 static void History(bool redo=false){UnityEditor.Undo.FlushUndoRecordObjects();StudioUndo.IncrementCurrentGroup();if(redo)StudioUndo.PerformRedo();else StudioUndo.PerformUndo();}
 static void Target(int node,StudioModelEditor.ComponentMode mode,params int[] ids){Call("ActivateComponentTarget",node,mode);editor.Components.Clear();editor.Components.UnionWith(ids);}
 static int[] Selection(int node){var record=((Array)Call("CaptureComponentTargets")).Cast<object>().Single(r=>(int)r.GetType().GetField("node").GetValue(r)==node);return (int[])record.GetType().GetField("components").GetValue(record);}
 static HashSet<int> Group(int id,StudioModelEditor.ComponentMode mode){var p=editor.ActiveMesh.vertices;if(mode==StudioModelEditor.ComponentMode.Vertex)return Enumerable.Range(0,p.Length).Where(i=>p[i]==p[id]).ToHashSet();if(mode==StudioModelEditor.ComponentMode.Face)return new HashSet<int>{id};var e=(List<(int a,int b)>)Call("Edges");var key=StudioMeshCuts.NormalEdgePositionKeyForBevel(p[e[id].a],p[e[id].b]);return Enumerable.Range(0,e.Count).Where(i=>StudioMeshCuts.NormalEdgePositionKeyForBevel(p[e[i].a],p[e[i].b])==key).ToHashSet();}
 public static void Run(){EditorApplication.delayCall+=()=>{Exception error=null;try{if(!Application.dataPath.Replace("\\","/").Contains("/obj/StudioControlsValidation/"))throw new Exception("Disposable project only");doc=ScriptableObject.CreateInstance<StudioModelDocument>();for(int i=0;i<2;i++){var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var polygons);doc.nodes.Add(new StudioModelDocument.Node{name="Cube "+i,mesh=mesh,cutPolygons=polygons,cutTriangles=mesh.triangles});}editor=new StudioModelEditor(()=>{});editor.Load(doc);editor.SelectObject(0);
 foreach(var mode in new[]{StudioModelEditor.ComponentMode.Vertex,StudioModelEditor.ComponentMode.Edge,StudioModelEditor.ComponentMode.Face}){
 editor.SetToolbarComponentMode(mode);int count=(int)Call("ComponentCount");var geometry=editor.ActiveMesh.vertices;Check(mode==StudioModelEditor.ComponentMode.Face||Group(0,mode).Count>1,"Fixture must contain seam aliases");
 for(int seed=0;seed<count;seed++){Target(0,mode,seed);var excluded=Group(seed,mode);Reset();Call("InvertSelection");var expected=Enumerable.Range(0,count).Where(i=>!excluded.Contains(i)).ToHashSet();Check(editor.Components.SetEquals(expected),mode+" seed "+seed+" did not exclude seam copies");Check(StudioUndo.RetainedActions==1,"Invert must be one history action");History();Check(editor.Components.SetEquals(new[]{seed}),"Undo lost exact source indices");History(true);Check(editor.Components.SetEquals(expected),"Redo lost complement");Call("InvertSelection");Check(editor.Components.SetEquals(excluded),"Double inversion must restore logical group");}
 Target(0,mode);Call("InvertSelection");Check(editor.Components.Count==count,"Invert empty must select all");Call("InvertSelection");Check(editor.Components.Count==0,"Invert all must clear");
 typeof(StudioModelEditor).GetField("weld",F).SetValue(editor,false);Target(0,mode,0);Call("InvertSelection");Check(editor.Components.SetEquals(Enumerable.Range(1,count-1)),"Unwelded mode must use raw indices");typeof(StudioModelEditor).GetField("weld",F).SetValue(editor,true);
 Check(editor.ActiveMesh.vertices.SequenceEqual(geometry),"Invert changed geometry");
 }
 foreach(var mode in new[]{StudioModelEditor.ComponentMode.Vertex,StudioModelEditor.ComponentMode.Edge,StudioModelEditor.ComponentMode.Face}){editor.SelectObject(0);editor.SelectObject(1,true);Target(0,mode,0);var g0=Group(0,mode);int n0=(int)Call("ComponentCount");Target(1,mode,1);var g1=Group(1,mode);int n1=(int)Call("ComponentCount");Reset();Call("InvertSelection");Check(Selection(0).ToHashSet().SetEquals(Enumerable.Range(0,n0).Where(i=>!g0.Contains(i))),"First multi-target complement");Check(Selection(1).ToHashSet().SetEquals(Enumerable.Range(0,n1).Where(i=>!g1.Contains(i))),"Second multi-target complement");Check(StudioUndo.RetainedActions==1,"Multi-target invert must share one Undo");History();Check(Selection(0).SequenceEqual(new[]{0})&&Selection(1).SequenceEqual(new[]{1}),"Multi-target Undo source");}
 }catch(Exception e){error=e;}File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../invert-components-result.txt")),error==null?"PASS "+checks+" seam-aware component inversion/history checks":error.ToString());EditorApplication.delayCall+=()=>{editor?.Dispose();if(doc){foreach(var n in doc.nodes)if(n.mesh)Object.DestroyImmediate(n.mesh);Object.DestroyImmediate(doc);}EditorApplication.Exit(error==null?0:1);};};}
}
